versions.variantCss:
.wemd-qr-card[data-variant="bytedance-qr-card"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 24px;
  margin: 16px 0;
  text-align: center;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-qr-card[data-variant="bytedance-qr-card"] .wemd-component-body {
  padding: 0;
}
.wemd-qr-card[data-variant="bytedance-qr-card"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-text-strong);
  font-size: 16px;
  font-weight: 700;
  margin: 0 0 12px 0;
}
.wemd-qr-card[data-variant="bytedance-qr-card"] .wemd-component-body .wemd-child-2 {
  display: inline-block;
  padding: 12px;
  background: #ffffff;
  border: 2px solid var(--wemd-primary);
  border-radius: 8px;
  margin: 0 0 12px 0;
}
.wemd-qr-card[data-variant="bytedance-qr-card"] .wemd-component-body .wemd-child-3 {
  color: var(--wemd-text-soft);
  font-size: 13px;
  margin: 0;
}
